enum GameStatus { IN_PROGRESS, WHITE_WINS, BLACK_WINS, STALEMATE }

enum PieceType { KING, QUEEN, ROOK, BISHOP, KNIGHT, PAWN }

class Spot {
  final int row, col;
  Piece piece;
  Spot(int r, int c, Piece p) { row = r; col = c; piece = p; }
  boolean isEmpty() { return piece == null; }
}

abstract class Piece {
  final boolean white;
  boolean hasMoved = false;
  Piece(boolean white) { this.white = white; }
  abstract PieceType type();
  abstract boolean canMove(Board b, Spot from, Spot to);
  protected boolean destOk(Board b, Spot to) {
    return to.isEmpty() || to.piece.white != white;
  }
}

class Knight extends Piece {
  Knight(boolean w) { super(w); }
  PieceType type() { return PieceType.KNIGHT; }
  public boolean canMove(Board b, Spot from, Spot to) {
    if (!destOk(b, to)) return false;
    int dr = Math.abs(from.row - to.row), dc = Math.abs(from.col - to.col);
    return (dr == 2 && dc == 1) || (dr == 1 && dc == 2);
  }
}

class Rook extends Piece {
  Rook(boolean w) { super(w); }
  PieceType type() { return PieceType.ROOK; }
  public boolean canMove(Board b, Spot from, Spot to) {
    if (!destOk(b, to)) return false;
    if (from.row != to.row && from.col != to.col) return false;
    return b.isPathClear(from, to);
  }
}

class Bishop extends Piece {
  Bishop(boolean w) { super(w); }
  PieceType type() { return PieceType.BISHOP; }
  public boolean canMove(Board b, Spot from, Spot to) {
    if (!destOk(b, to)) return false;
    if (Math.abs(from.row - to.row) != Math.abs(from.col - to.col)) return false;
    return b.isPathClear(from, to);
  }
}

class Queen extends Piece {
  Queen(boolean w) { super(w); }
  PieceType type() { return PieceType.QUEEN; }
  public boolean canMove(Board b, Spot from, Spot to) {
    if (!destOk(b, to)) return false;
    boolean straight = from.row == to.row || from.col == to.col;
    boolean diag = Math.abs(from.row - to.row) == Math.abs(from.col - to.col);
    if (!straight && !diag) return false;
    return b.isPathClear(from, to);
  }
}

class King extends Piece {
  King(boolean w) { super(w); }
  PieceType type() { return PieceType.KING; }
  public boolean canMove(Board b, Spot from, Spot to) {
    if (!destOk(b, to)) return false;
    int dr = Math.abs(from.row - to.row), dc = Math.abs(from.col - to.col);
    return dr <= 1 && dc <= 1 && (dr + dc > 0);
    // Castling handled in Game, not here: it needs attacked-square info.
  }
}

class Pawn extends Piece {
  Pawn(boolean w) { super(w); }
  PieceType type() { return PieceType.PAWN; }
  public boolean canMove(Board b, Spot from, Spot to) {
    int dir = white ? -1 : 1;
    int dr = to.row - from.row, dc = to.col - from.col;
    // forward
    if (dc == 0) {
      if (dr == dir && to.isEmpty()) return true;
      int start = white ? 6 : 1;
      if (from.row == start && dr == 2 * dir && to.isEmpty()
          && b.getSpot(from.row + dir, from.col).isEmpty()) return true;
      return false;
    }
    // diagonal capture (en passant checked in Game)
    if (Math.abs(dc) == 1 && dr == dir)
      return !to.isEmpty() && to.piece.white != white;
    return false;
  }
}

class Board {
  final Spot[][] grid = new Spot[8][8];
  Board() { for (int r = 0; r < 8; r++) for (int c = 0; c < 8; c++) grid[r][c] = new Spot(r, c, null); }
  Spot getSpot(int r, int c) { return grid[r][c]; }
  boolean inBounds(int r, int c) { return r >= 0 && r < 8 && c >= 0 && c < 8; }
  boolean isPathClear(Spot from, Spot to) {
    int dr = Integer.signum(to.row - from.row), dc = Integer.signum(to.col - from.col);
    int r = from.row + dr, c = from.col + dc;
    while (r != to.row || c != to.col) {
      if (!grid[r][c].isEmpty()) return false;
      r += dr; c += dc;
    }
    return true;
  }
  Spot findKing(boolean white) {
    for (Spot[] row : grid) for (Spot s : row)
      if (!s.isEmpty() && s.piece.type() == PieceType.KING && s.piece.white == white) return s;
    return null;
  }
  boolean isSquareAttacked(int r, int c, boolean byWhite) {
    Spot target = grid[r][c];
    for (Spot[] row : grid) for (Spot s : row) {
      if (s.isEmpty() || s.piece.white != byWhite) continue;
      if (s.piece.type() == PieceType.PAWN) {
        int dir = byWhite ? -1 : 1;
        if (s.row + dir == r && Math.abs(s.col - c) == 1) return true;
      } else if (s.piece.canMove(this, s, target)) return true;
    }
    return false;
  }
}

class Move {
  Spot from, to; Piece moved, captured; boolean isEnPassant, isCastle;
  Move(Spot f, Spot t) { from = f; to = t; moved = f.piece; captured = t.piece; }
}

class Game {
  final Board board = new Board();
  boolean whiteToMove = true;
  Move lastMove;
  GameStatus status = GameStatus.IN_PROGRESS;
  // setup() places standard pieces; omitted for brevity

  boolean makeMove(int fr, int fc, int tr, int tc) {
    if (!board.inBounds(fr, fc) || !board.inBounds(tr, tc)) return false;
    Spot from = board.getSpot(fr, fc), to = board.getSpot(tr, tc);
    if (from.isEmpty() || from.piece.white != whiteToMove) return false;
    if (from.row == tr && from.col == fc) return false;
    Piece p = from.piece;
    boolean ok = p.canMove(board, from, to)
        || tryEnPassant(from, to) || tryCastling(from, to);
    if (!ok) return false;
    // trial: apply, test own king, revert if illegal
    if (leavesKingInCheck(from, to, p)) return false;
    commitMove(from, to, p, tr, tc);
    whiteToMove = !whiteToMove;
    updateStatus();
    return true;
  }

  private boolean leavesKingInCheck(Spot from, Spot to, Piece p) {
    Piece savedTo = to.piece;
    Spot enPassantVictim = enPassantVictim(from, to);
    Piece savedVictim = enPassantVictim == null ? null : enPassantVictim.piece;
    if (enPassantVictim != null) enPassantVictim.piece = null;
    to.piece = p; from.piece = null;
    Spot king = board.findKing(p.white);
    boolean inCheck = board.isSquareAttacked(king.row, king.col, !p.white);
    from.piece = p; to.piece = savedTo; // revert
    if (enPassantVictim != null) enPassantVictim.piece = savedVictim;
    return inCheck;
  }

  private void commitMove(Spot from, Spot to, Piece p, int tr, int tc) {
    Spot victim = enPassantVictim(from, to);
    if (victim != null) victim.piece = null;
    if (isCastleMove(from, to, p)) moveRookForCastle(tr, tc);
    to.piece = p; from.piece = null; p.hasMoved = true;
    // promotion: default queen, real UI would ask
    if (p.type() == PieceType.PAWN && (tr == 0 || tr == 7))
      to.piece = new Queen(p.white);
    lastMove = new Move(from, to);
  }

  private boolean tryEnPassant(Spot from, Spot to) {
    if (from.piece.type() != PieceType.PAWN || !to.isEmpty()) return false;
    Spot v = enPassantVictim(from, to);
    return v != null;
  }
  private Spot enPassantVictim(Spot from, Spot to) {
    if (from.piece.type() != PieceType.PAWN) return null;
    if (Math.abs(from.col - to.col) != 1 || to.row - from.row != (from.piece.white ? -1 : 1)) return null;
    if (!to.isEmpty() || lastMove == null) return null;
    Spot beside = board.getSpot(from.row, to.col);
    boolean doubleStep = Math.abs(lastMove.from.row - lastMove.to.row) == 2
        && lastMove.to == beside && beside.piece != null
        && beside.piece.type() == PieceType.PAWN;
    return doubleStep ? beside : null;
  }
  private boolean tryCastling(Spot from, Spot to) { return isCastleMove(from, to, from.piece); }
  private boolean isCastleMove(Spot from, Spot to, Piece p) {
    if (p.type() != PieceType.KING || p.hasMoved) return false;
    if (from.row != to.row || Math.abs(from.col - to.col) != 2) return false;
    int r = from.row; boolean kingside = to.col > from.col;
    Spot rookSpot = board.getSpot(r, kingside ? 7 : 0);
    if (rookSpot.isEmpty() || rookSpot.piece.type() != PieceType.ROOK || rookSpot.piece.hasMoved) return false;
    int step = kingside ? 1 : -1;
    for (int c = from.col + step; kingside ? c < 7 : c > 0; c += step)
      if (!board.getSpot(r, c).isEmpty()) return false;
    // king may not pass through or land in check
    for (int c = from.col; kingside ? c <= to.col : c >= to.col; c += step)
      if (board.isSquareAttacked(r, c, !p.white)) return false;
    return true;
  }
  private void moveRookForCastle(int kr, int kc) {
    boolean kingside = kc == 6;
    Spot rf = board.getSpot(kr, kingside ? 7 : 0), rt = board.getSpot(kr, kingside ? 5 : 3);
    rt.piece = rf.piece; rf.piece = null; rt.piece.hasMoved = true;
  }
  boolean isInCheck(boolean white) {
    Spot k = board.findKing(white); return board.isSquareAttacked(k.row, k.col, !white);
  }
  boolean hasAnyLegalMove(boolean white) {
    for (Spot[] row : board.grid) for (Spot f : row) {
      if (f.isEmpty() || f.piece.white != white) continue;
      for (int r = 0; r < 8; r++) for (int c = 0; c < 8; c++) {
        Spot t = board.getSpot(r, c);
        boolean cand = f.piece.canMove(board, f, t) || tryEnPassant(f, t) || tryCastling(f, t);
        if (cand && !leavesKingInCheck(f, t, f.piece)) return true;
      }
    }
    return false;
  }
  void updateStatus() {
    boolean whiteInCheck = isInCheck(true), blackInCheck = isInCheck(false);
    boolean sideToMoveHasMoves = hasAnyLegalMove(whiteToMove);
    if (!sideToMoveHasMoves) status = whiteToMove == whiteInCheck
        ? (whiteToMove ? GameStatus.BLACK_WINS : GameStatus.WHITE_WINS)
        : GameStatus.STALEMATE;
  }
}

from abc import ABC, abstractmethod

class Piece(ABC):
    def __init__(self, white: bool):
        self.white = white
        self.has_moved = False
    @abstractmethod
    def can_move(self, board, fr, fc, tr, tc) -> bool: ...

class Knight(Piece):
    def can_move(self, board, fr, fc, tr, tc):
        if not board.dest_ok(self.white, tr, tc): return False
        dr, dc = abs(fr-tr), abs(fc-tc)
        return (dr, dc) in ((2,1),(1,2))

class SlidingMixin:
    def path_clear(self, board, fr, fc, tr, tc):
        dr = (tr-fr and (1 if tr>fr else -1))
        dc = (tc-fc and (1 if tc>fc else -1))
        r, c = fr+dr, fc+dc
        while (r,c) != (tr,tc):
            if board.piece_at(r,c) is not None: return False
            r, c = r+dr, c+dc
        return True

